from pathlib import Path
import json, sys, time

TARGET='BRIDGE-ACTIVE-PAGE-ACCEPT-20260929-E003'
SESSION='SESSION-ROUTE-06b02c18b66873daa2c4548a'
home=Path.home()
state_path=home/'.local/state/prediction-command-bus/tasks'/f'{TARGET}.json'
route_path=home/'.local/share/prediction-chat-bridge/routes'/f'{SESSION}.json'
active_path=home/'.local/share/prediction-chat-bridge/active_page.json'
bridge=home/'.local/share/prediction-chat-bridge'

def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8'))
        return x if isinstance(x,dict) else None
    except Exception:
        return None

def fail(code):
    print('ERROR_CLASS='+code)
    raise SystemExit(2)

state=load(state_path)
if not state:
    fail('E003_TASK_STATE_MISSING')
status=str(state.get('status') or 'UNKNOWN')
print('E003_STATE='+status)
if status!='DISPATCHED':
    fail('E003_'+status)
if str(state.get('route_source') or '')!='active_page':
    fail('E003_ROUTE_SOURCE_'+str(state.get('route_source') or 'MISSING').upper().replace(':','_'))
session=load(route_path)
if not session:
    fail('SESSION_ROUTE_FILE_MISSING')
if str(state.get('chat_id') or '')!=str(session.get('chat_id') or ''):
    fail('E003_WRONG_CHAT')
if not str(state.get('consumer_id') or ''):
    fail('E003_CONSUMER_MISSING')
active=load(active_path)
if not active:
    fail('ACTIVE_PAGE_FILE_MISSING')
if str(active.get('source') or '')!='tampermonkey_focus_presence':
    fail('ACTIVE_PAGE_BAD_SOURCE')
locations=[]
for name in ('outbox','inflight','sent'):
    d=bridge/name
    if not d.exists():
        continue
    for p in d.glob('*.json'):
        obj=load(p)
        if obj and str(obj.get('task_id') or '')==TARGET:
            locations.append(name)
            break
print('E003_EVENT_LOCATIONS='+','.join(locations))
if 'sent' not in locations:
    if 'inflight' in locations:
        fail('E003_RESULT_INFLIGHT_NOT_ACKED')
    if 'outbox' in locations:
        fail('E003_RESULT_OUTBOX_NOT_LEASED')
    fail('E003_RESULT_EVENT_NOT_FOUND')
print('E003_ACTIVE_PAGE_ACCEPTANCE=PASS')
